from .contracts import NarrationPlan, ProviderProfile
from .pronunciation import expand, digest

VERSION = "0.1.0"
LANGUAGES = {
    ("elevenlabs", "eleven_v4"): {"en-IN", "hi-IN", "as-IN"},
    ("elevenlabs", "eleven_v3"): {"en-IN", "hi-IN", "as-IN"},
