    "curious": "Invite a genuine prediction, curious without theatrical suspense.",
    "steady": "Explain conversationally with clear causal emphasis.",
    "deliberate": "Measure each phrase carefully; distinguish scientific terms and conditions.",
    "light": "Allow a small amused smile in the delivery, without added laughter.",
    "reassuring": "Be warm and matter-of-fact; make correction feel specific and repairable.",
    "focused": "Be precise and credible, not promotional.",
}
# Tags are provider-specific; exact pauses are never implemented with these.
ELEVEN_TAG = {"curious":"[curious] ", "steady":"", "deliberate":"[calm] ",
              "light":"", "reassuring":"[calm] ", "focused":""}


def compile_plan(plan: NarrationPlan, profile: ProviderProfile, lexicon: dict, production=False) -> dict:
    key = (profile.provider, profile.model)
    if key not in LANGUAGES:
        raise ValueError("Unreviewed provider/model contract: add and test explicitly")
    if plan.voice.locale not in LANGUAGES[key]:
        raise ValueError("Language is not admitted by this model contract")
    if production:
        if plan.voice.rights_status not in {"licensed-stock", "consented-custom"}:
            raise ValueError("Production voice rights are not cleared")
        if not profile.live_contract_verified:
            raise ValueError("Live endpoint contract has not been approved")
        if "REPLACE" in profile.voice_id.upper():
            raise ValueError("Replace placeholder with the approved provider voice ID")
    if plan.lexicon_version != lexicon["version"]:
        raise ValueError("Lexicon version mismatch")
    requests = []
    for segment in plan.segments:
        text = expand(segment.text_template, lexicon, plan.voice.locale)
        caption = expand(segment.text_template, lexicon, plan.voice.locale, "caption")
        style = " ".join([plan.voice.brief, STYLE[segment.direction.mode],
                  f"Aim for approximately {segment.direction.target_wpm} spoken words per minute; do not add words.",
                  ("Emphasize: " + "; ".join(segment.direction.emphasis)) if segment.direction.emphasis else "",
                  segment.direction.notes]).strip()
        warnings = ["Request compiled offline; endpoint behavior and pronunciation need live approval."]
        if len(text) > 1800:
            raise ValueError("Split at a sentence boundary: this scaffold caps segments at 1800 characters")
        headers = {"Content-Type":"application/json"}
        if profile.provider == "elevenlabs":
            headers["xi-api-key"] = "ENV:ELEVENLABS_API_KEY"
            tagged = text if profile.model == "eleven_multilingual_v2" else ELEVEN_TAG[segment.direction.mode] + text
            if profile.model == "eleven_v4":
                endpoint = "https://api.elevenlabs.io/v1/text-to-dialogue"
                payload = {"model_id":profile.model, "inputs":[{"text":tagged,"voice_id":profile.voice_id}],
                           "language_code":plan.voice.locale.split('-')[0]}
                # No v2 speed/style knobs or SSML: v4 differs. Use text and auditions.
            else:
                endpoint = f"https://api.elevenlabs.io/v1/text-to-speech/{profile.voice_id}"
                payload = {"model_id":profile.model, "text":tagged}
                if profile.model == "eleven_v3":
                    payload["language_code"] = plan.voice.locale.split('-')[0]
            warnings.append("WPM/detailed acting cues are editorial targets; not every cue has an exact API control.")
        elif profile.provider == "cartesia":
            if not profile.api_version:
                raise ValueError("Cartesia-Version must be selected from a verified API contract")
            endpoint = "https://api.cartesia.ai/tts/bytes"
            headers.update({"Authorization":"Bearer ENV:CARTESIA_API_KEY", "Cartesia-Version":profile.api_version})
            payload = {"model_id":profile.model, "transcript":text, "voice":{"mode":"id","id":profile.voice_id},
                       "language":plan.voice.locale.split('-')[0],
                       "output_format":{"container":"wav","encoding":"pcm_s16le","sample_rate":48000},
                       "generation_config":{"speed":round(max(.6,min(1.5,segment.direction.target_wpm/145)),3),"volume":1}}
            warnings.append("Speed multiplier is a starting heuristic, not a WPM guarantee. Emotion beta is not enabled.")
        elif profile.provider == "gemini":
            endpoint = "https://generativelanguage.googleapis.com/v1beta/interactions"
            headers["x-goog-api-key"] = "ENV:GEMINI_API_KEY"
            payload = {"model":profile.model,"input":[{"type":"user_input","content":[{
                "type":"text","text":text,"annotations":[{"type":"speech_metadata","style":style}]}]}],
                "response_format":{"type":"audio"},"generation_config":{"speech_config":[{"voice":profile.voice_id}]}}
            warnings.append("Unary 3.8 output is WAV; do not prepend an extra WAV header. Streaming differs.")
        else:
            endpoint = "https://api.openai.com/v1/audio/speech"
            headers["Authorization"] = "Bearer ENV:OPENAI_API_KEY"
            payload = {"model":profile.model,"voice":profile.voice_id,"input":text,"instructions":style,"response_format":"wav"}
        speech_inputs = {"compiler":VERSION,"text":text,"profile":profile.model_dump(),
             "voice":plan.voice.model_dump(),"direction":segment.direction.model_dump(),
             "lexicon_digest":digest(lexicon)}
        # Visuals and planned silence do NOT belong to the speech cache key.
        requests.append({"segment_id":segment.segment_id,"method":"POST","url":endpoint,
                         "headers_template":headers,"body":payload,"canonical_spoken":text,
                         "caption_text":caption,"audio_cache_key":digest(speech_inputs),
                         "editorial_style":style,"warnings":warnings})
    return {"status":"offline-request-compilation-not-live-integration","lesson_id":plan.lesson_id,
            "requests":requests,"network_operations":0}
