from __future__ import annotations
from pathlib import Path
from fractions import Fraction
import math
import numpy as np
import soundfile as sf
from scipy.signal import resample_poly
from .contracts import NarrationPlan, Alignment
from .pronunciation import normalized_words, expand, digest
from .cache import file_hash


def frame_at(sample: int, sample_rate: int, fps_num=30, fps_den=1):
    # Round each GLOBAL timestamp, not per-segment durations: no accumulated frame drift.
    x = Fraction(sample*fps_num, sample_rate*fps_den)
    return (2*x.numerator+x.denominator)//(2*x.denominator)


def validate_alignment(record: Alignment, text: str, audio_path: Path, duration: float):
    if record.audio_sha256 != file_hash(audio_path):
        raise ValueError("Alignment belongs to different audio")
    if record.transcript_sha256 != digest(text):
        raise ValueError("Alignment belongs to different normalized speech")
    if normalized_words(' '.join(w.text for w in record.words)) != normalized_words(text):
        raise ValueError("Alignment word sequence does not match the transcript")
    if not record.words or record.words[-1].end > duration + .001:
        raise ValueError("Alignment extends beyond decoded audio or is empty")


def cue_time(cue, words):
    # Word tokens must be individually aligned. Never select the first repeated word silently.
    tokens = [normalized_words(w.text) for w in words]
    if any(len(t) != 1 for t in tokens):
        raise ValueError("Cue alignment expects one normalized token per word")
    flat = [t[0] for t in tokens]; phrase = normalized_words(cue.phrase)
    matches = [i for i in range(len(flat)-len(phrase)+1) if flat[i:i+len(phrase)] == phrase]
    if len(matches) < cue.occurrence:
        raise ValueError(f"Missing cue phrase/occurrence: {cue.cue_id}")
    i = matches[cue.occurrence-1]
    return words[i].start if cue.edge == 'start' else words[i+len(phrase)-1].end


def compose(plan: NarrationPlan, lexicon: dict, audio_paths: dict, alignments: dict,
            output: Path, sample_rate=48000, fps_num=30, fps_den=1):
